import { Node, mergeAttributes } from "@tiptap/core";
import { ReactNodeViewRenderer } from "@tiptap/react";

import { MermaidView } from "./view";

export { MermaidPreview } from "./preview";
export type { MermaidPreviewProps } from "./preview";
export { mermaidSlashCommandItem } from "./slash-command-item";

export interface MermaidAttributes {
  value: string | null;
}

export interface MermaidOptions {
  HTMLAttributes: Record<string, unknown>;
}

declare module "@tiptap/core" {
  interface Commands<ReturnType> {
    mermaid: {
      setMermaid: (attributes?: Partial<MermaidAttributes>) => ReturnType;
    };
  }
}

const FENCE_OPEN = /^ {0,3}(`{3,}|~{3,})[ \t]*mermaid(?:[ \t][^\n]*)?(?:\n|$)/;
const FENCE_OPEN_ANYWHERE = new RegExp(FENCE_OPEN.source, "m");

const longestRun = (value: string, char: string) => {
  let longest = 0;
  for (const run of value.match(new RegExp(`\\${char}+`, "g")) ?? []) {
    longest = Math.max(longest, run.length);
  }
  return longest;
};

export const Mermaid = Node.create<MermaidOptions>({
  addAttributes() {
    return {
      value: {
        default: null,
        parseHTML: (element) => element.textContent || null,
        rendered: false,
      },
    };
  },

  addCommands() {
    return {
      setMermaid:
        (attributes) =>
        ({ commands }) =>
          commands.insertContent({
            attrs: { value: attributes?.value ?? null },
            type: this.name,
          }),
    };
  },

  addNodeView() {
    return ReactNodeViewRenderer(MermaidView);
  },

  addOptions() {
    return {
      HTMLAttributes: {},
    };
  },

  atom: true,
  group: "block",

  markdownTokenName: "mermaid",

  markdownTokenizer: {
    level: "block",
    name: "mermaid",
    start: (src: string) => {
      const match = FENCE_OPEN_ANYWHERE.exec(src);
      return match ? match.index : -1;
    },
    tokenize: (src: string) => {
      const open = FENCE_OPEN.exec(src);
      const fence = open?.[1];
      if (!open || !fence) {
        return;
      }
      const afterOpen = src.slice(open[0].length);
      const close = new RegExp(
        `^ {0,3}\\${fence[0]}{${fence.length},}[ \\t]*$`,
        "m"
      ).exec(afterOpen);
      const body = close ? afterOpen.slice(0, close.index) : afterOpen;
      let rawLength = close
        ? open[0].length + close.index + close[0].length
        : src.length;
      if (src[rawLength] === "\n") {
        rawLength += 1;
      }
      return {
        raw: src.slice(0, rawLength),
        text: body.endsWith("\n") ? body.slice(0, -1) : body,
        type: "mermaid",
      };
    },
  },

  name: "mermaid",

  parseHTML() {
    return [{ tag: 'div[data-type="mermaid"]' }];
  },

  parseMarkdown: (token, helpers) =>
    helpers.createNode("mermaid", { value: token.text || null }),

  renderHTML({ HTMLAttributes, node }) {
    return [
      "div",
      mergeAttributes(this.options.HTMLAttributes, HTMLAttributes, {
        "data-type": "mermaid",
      }),
      ["pre", ["code", { class: "language-mermaid" }, node.attrs.value ?? ""]],
    ];
  },

  renderMarkdown: (node) => {
    const value = (node.attrs?.value as string | null) ?? "";
    const fence = "`".repeat(Math.max(3, longestRun(value, "`") + 1));
    return value
      ? `${fence}mermaid\n${value}\n${fence}`
      : `${fence}mermaid\n${fence}`;
  },
});

"use client";

import { useEffect, useRef, useState, useSyncExternalStore } from "react";

import { cn } from "../ui/utils";

type MermaidTheme = "dark" | "default";

const RENDER_DELAY = 300;
const CACHE_LIMIT = 100;

const cache = new Map<string, string>();
let queue: Promise<unknown> = Promise.resolve();
let renderCount = 0;

const settled = async (promise: Promise<unknown>) => {
  try {
    return await promise;
  } catch (error) {
    return error;
  }
};

const renderDiagram = (source: string, theme: MermaidTheme) => {
  const previous = queue;
  const task = (async () => {
    await previous;
    const { default: mermaid } = await import("mermaid");
    mermaid.initialize({
      securityLevel: "strict",
      startOnLoad: false,
      suppressErrorRendering: true,
      theme,
    });
    renderCount += 1;
    const { svg } = await mermaid.render(`ext-mermaid-${renderCount}`, source);
    return svg;
  })();
  queue = settled(task);
  return task;
};

const remember = (key: string, svg: string) => {
  cache.delete(key);
  cache.set(key, svg);
  if (cache.size > CACHE_LIMIT) {
    const oldest = cache.keys().next().value;
    if (oldest !== undefined) {
      cache.delete(oldest);
    }
  }
};

const subscribeToTheme = (onChange: () => void) => {
  const observer = new MutationObserver(onChange);
  observer.observe(document.documentElement, {
    attributeFilter: ["class"],
    attributes: true,
  });
  return () => observer.disconnect();
};

const useMermaidTheme = (): MermaidTheme =>
  useSyncExternalStore(
    subscribeToTheme,
    () =>
      document.documentElement.classList.contains("dark") ? "dark" : "default",
    () => "default"
  );

interface RenderState {
  error?: string;
  key: string;
  svg?: string;
}

export interface MermaidPreviewProps {
  className?: string;
  value: string | null;
}

export const MermaidPreview = ({ className, value }: MermaidPreviewProps) => {
  const source = value?.trim() ?? "";
  const theme = useMermaidTheme();
  const key = `${theme}\n${source}`;
  const [state, setState] = useState<RenderState>(() => ({
    key,
    svg: cache.get(key),
  }));
  const rendered = useRef(Boolean(state.svg));

  useEffect(() => {
    if (!source) {
      return;
    }
    if (cache.has(key)) {
      rendered.current = true;
      return;
    }
    let cancelled = false;
    const timer = setTimeout(
      async () => {
        try {
          const svg = await renderDiagram(source, theme);
          remember(key, svg);
          if (!cancelled) {
            rendered.current = true;
            setState({ key, svg });
          }
        } catch (error) {
          if (!cancelled) {
            setState((current) => ({
              error:
                error instanceof Error
                  ? error.message
                  : "Failed to render diagram",
              key,
              svg: current.svg,
            }));
          }
        }
      },
      rendered.current ? RENDER_DELAY : 0
    );
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [key, source, theme]);

  if (!source) {
    return (
      <div
        className={cn(
          "ext-mermaid-empty flex min-h-32 items-center justify-center p-6 text-center text-xs text-muted-foreground",
          className
        )}
      >
        Empty diagram. Open the Code tab to write one.
      </div>
    );
  }

  const error = state.key === key ? state.error : undefined;
  const svg = cache.get(key) ?? state.svg;

  if (!svg) {
    return (
      <div className={cn("ext-mermaid-fallback", className)}>
        <output
          className={cn(
            "block px-4 pt-3 font-mono text-xs whitespace-pre-wrap",
            error ? "text-destructive" : "text-muted-foreground"
          )}
        >
          {error ?? "Rendering diagram..."}
        </output>
        <pre className="m-0 overflow-x-auto bg-transparent p-4 font-mono text-xs">
          <code>{source}</code>
        </pre>
      </div>
    );
  }

  return (
    <div className={cn("ext-mermaid-preview flex flex-col", className)}>
      {error && (
        <output className="ext-mermaid-error block px-4 pt-3 font-mono text-xs whitespace-pre-wrap text-destructive">
          {error}
        </output>
      )}
      <div
        className={cn(
          "ext-mermaid-svg flex justify-center overflow-auto p-4 [&_svg]:h-auto [&_svg]:max-w-full",
          error && "opacity-50"
        )}
        dangerouslySetInnerHTML={{ __html: svg }}
      />
    </div>
  );
};

import type { SlashCommandItem } from "../core/types";

/** Slash command item for the `@editorcn/block-editor` menu. */
export const mermaidSlashCommandItem: SlashCommandItem = {
  command: ({ editor, range }) => {
    if (!editor.can().setMermaid()) {
      return;
    }
    editor.chain().focus().deleteRange(range).setMermaid().run();
  },
  description: "Draw a flowchart, sequence or other diagram with Mermaid.",
  id: "mermaid",
  keywords: ["mermaid", "diagram", "flowchart", "chart", "sequence", "graph"],
  title: "Diagram",
};

"use client";

import { NodeViewWrapper } from "@tiptap/react";
import type { ReactNodeViewProps } from "@tiptap/react";
import { Check, Copy, Trash2 } from "lucide-react";
import { useEffect, useState } from "react";

import { useEditable } from "../core/editor-state";
import { Button } from "../ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "../ui/tabs";
import { MermaidPreview } from "./preview";

const PLACEHOLDER = `graph TD
  A[Start] --> B{Is it working?}
  B -->|Yes| C[Ship it]
  B -->|No| D[Debug]
  D --> B`;

const TOOLBAR_BUTTON_CLASS = "size-6 rounded-sm [&>svg]:size-3.5";

export const MermaidView = ({
  deleteNode,
  editor,
  node,
  updateAttributes,
}: ReactNodeViewProps<HTMLDivElement>) => {
  const editable = useEditable(editor);
  const value = (node.attrs.value as string | null) ?? "";
  const [draft, setDraft] = useState(value);
  const [synced, setSynced] = useState(value);
  const [copied, setCopied] = useState(false);

  if (value !== synced) {
    setSynced(value);
    setDraft(value);
  }

  useEffect(() => {
    if (!copied) {
      return;
    }
    const timer = setTimeout(() => setCopied(false), 2000);
    return () => clearTimeout(timer);
  }, [copied]);

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(value);
      setCopied(true);
    } catch {
      setCopied(false);
    }
  };

  return (
    <NodeViewWrapper className="ext-mermaid my-2" data-type="mermaid">
      <Tabs
        defaultValue={value ? "preview" : "code"}
        className="ext-mermaid-box rounded-[var(--radius)] border border-border bg-[color-mix(in_srgb,var(--muted)_60%,transparent)]"
      >
        <div
          className="ext-mermaid-header flex items-center justify-between gap-2 px-2 pt-2"
          contentEditable={false}
        >
          <TabsList className="ext-mermaid-tabs p-0.5">
            <TabsTrigger value="preview" className="px-2 py-0.5 text-xs">
              Preview
            </TabsTrigger>
            <TabsTrigger value="code" className="px-2 py-0.5 text-xs">
              Code
            </TabsTrigger>
          </TabsList>
          <div className="ext-mermaid-toolbar flex gap-0.5 text-muted-foreground">
            <Button
              size="icon-sm"
              className={TOOLBAR_BUTTON_CLASS}
              aria-label="Copy"
              tooltip="Copy"
              disabled={!value}
              onClick={copy}
            >
              {copied ? <Check /> : <Copy />}
            </Button>
            {editable && (
              <Button
                size="icon-sm"
                className={TOOLBAR_BUTTON_CLASS}
                aria-label="Delete"
                tooltip="Delete"
                danger
                onClick={deleteNode}
              >
                <Trash2 />
              </Button>
            )}
          </div>
        </div>
        <TabsContent value="preview" className="pt-0" contentEditable={false}>
          <MermaidPreview value={value} />
        </TabsContent>
        <TabsContent value="code" className="pt-0">
          <textarea
            aria-label="Mermaid source"
            className="ext-mermaid-source block min-h-40 w-full resize-y border-0 bg-transparent p-4 font-mono text-xs leading-relaxed text-foreground outline-none placeholder:text-muted-foreground"
            placeholder={PLACEHOLDER}
            readOnly={!editable}
            spellCheck={false}
            value={draft}
            onChange={(event) => {
              setDraft(event.target.value);
              updateAttributes({ value: event.target.value || null });
            }}
          />
        </TabsContent>
      </Tabs>
    </NodeViewWrapper>
  );
};

import * as React from "react";

import { useFloating } from "./use-floating";
import { cn } from "./utils";

export type ButtonSize = "default" | "icon" | "icon-sm";

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  active?: boolean;
  danger?: boolean;
  size?: ButtonSize;
  tooltip?: string;
}

const sizeClasses: Record<ButtonSize, string> = {
  default: "px-2.5",
  icon: "ext-btn--icon w-8 px-0",
  "icon-sm": "ext-btn--icon-sm w-7 px-0",
};

const PlainButton = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className,
      active = false,
      danger = false,
      size = "default",
      tooltip: _tooltip,
      type = "button",
      ...props
    },
    ref
  ) => {
    const cls = cn(
      "ext-btn inline-flex h-8 shrink-0 cursor-pointer items-center justify-center gap-1.5 rounded-md border border-transparent bg-transparent text-[0.8125rem] font-medium whitespace-nowrap text-inherit outline-none [transition:background-color_150ms_ease-out,color_150ms_ease-out,border-color_150ms_ease-out,scale_100ms_ease-out] hover:bg-accent hover:text-accent-foreground focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ring focus-visible:outline-solid active:scale-96 disabled:pointer-events-none disabled:opacity-50 [&>svg]:size-4 [&>svg]:shrink-0",
      sizeClasses[size],
      active && "ext-btn--active bg-accent text-accent-foreground",
      danger &&
        "ext-btn--danger text-destructive hover:bg-destructive/10 hover:text-destructive",
      className
    );

    return (
      <button
        ref={ref}
        type={type}
        className={cls}
        data-state={active ? "on" : "off"}
        aria-pressed={active}
        {...props}
      />
    );
  }
);
PlainButton.displayName = "PlainButton";

const TooltipButton = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      tooltip,
      onBlur,
      onFocus,
      onPointerDown,
      onPointerEnter,
      onPointerLeave,
      ...props
    },
    ref
  ) => {
    const [open, setOpen] = React.useState(false);
    const { content, triggerRef } = useFloating({
      onOpenChange: setOpen,
      open,
      sideOffset: 6,
    });

    const setRef = (node: HTMLButtonElement | null) => {
      triggerRef.current = node;
      if (typeof ref === "function") {
        ref(node);
      } else if (ref) {
        ref.current = node;
      }
    };

    return (
      <>
        <PlainButton
          ref={setRef}
          onBlur={(event) => {
            setOpen(false);
            onBlur?.(event);
          }}
          onFocus={(event) => {
            setOpen(event.currentTarget.matches(":focus-visible"));
            onFocus?.(event);
          }}
          onPointerDown={(event) => {
            setOpen(false);
            onPointerDown?.(event);
          }}
          onPointerEnter={(event) => {
            setOpen(true);
            onPointerEnter?.(event);
          }}
          onPointerLeave={(event) => {
            setOpen(false);
            onPointerLeave?.(event);
          }}
          {...props}
        />
        {content(
          <div
            className="ext-tooltip pointer-events-none animate-ext-tooltip-in rounded-none bg-foreground px-3 py-1.5 text-xs whitespace-nowrap text-background"
            role="tooltip"
          >
            {tooltip}
          </div>
        )}
      </>
    );
  }
);
TooltipButton.displayName = "TooltipButton";

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>((props, ref) =>
  props.tooltip ? (
    <TooltipButton ref={ref} {...props} />
  ) : (
    <PlainButton ref={ref} {...props} />
  )
);
Button.displayName = "Button";

export { Button };

import * as React from "react";
import { useContext, useState } from "react";

import { cn } from "./utils";

interface TabsState {
  setValue: (value: string) => void;
  value: string;
}

const TabsContext = React.createContext<TabsState | null>(null);

export interface TabsProps {
  children: React.ReactNode;
  className?: string;
  defaultValue: string;
}

const Tabs = ({ children, className, defaultValue }: TabsProps) => {
  const [value, setValue] = useState(defaultValue);

  return (
    <div className={cn("ext-tabs flex flex-col", className)}>
      <TabsContext.Provider value={{ setValue, value }}>
        {children}
      </TabsContext.Provider>
    </div>
  );
};

const useTabs = (): TabsState => {
  const context = useContext(TabsContext);
  if (!context) {
    throw new Error("TabsTrigger and TabsContent must be used inside Tabs");
  }
  return context;
};

export type TabsListProps = React.HTMLAttributes<HTMLDivElement>;

const TabsList = React.forwardRef<HTMLDivElement, TabsListProps>(
  ({ className, ...props }, ref) => (
    <div
      ref={ref}
      role="tablist"
      className={cn(
        "ext-tabs-list flex w-fit gap-0.5 rounded-sm bg-muted p-1",
        className
      )}
      {...props}
    />
  )
);
TabsList.displayName = "TabsList";

export interface TabsTriggerProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  value: string;
}

const TabsTrigger = React.forwardRef<HTMLButtonElement, TabsTriggerProps>(
  ({ className, onClick, value, ...props }, ref) => {
    const { setValue, value: current } = useTabs();
    const isActive = current === value;
    const cls = cn(
      "ext-tabs-trigger inline-flex cursor-pointer items-center gap-1.5 rounded-[calc(var(--radius)-6px)] border-none bg-transparent px-2.5 py-1 text-[0.8125rem] whitespace-nowrap text-muted-foreground [transition:background-color_150ms_ease-out,color_150ms_ease-out] hover:text-foreground hover:outline-none focus-visible:text-foreground focus-visible:outline-none [&>svg]:size-4 [&>svg]:shrink-0",
      isActive &&
        "ext-tabs-trigger--active bg-background text-foreground shadow-[0_1px_2px_rgba(0,0,0,0.06)]",
      className
    );

    return (
      <button
        ref={ref}
        aria-selected={isActive}
        className={cls}
        role="tab"
        type="button"
        onClick={(event) => {
          setValue(value);
          onClick?.(event);
        }}
        {...props}
      />
    );
  }
);
TabsTrigger.displayName = "TabsTrigger";

export interface TabsContentProps extends React.HTMLAttributes<HTMLDivElement> {
  value: string;
}

const TabsContent = React.forwardRef<HTMLDivElement, TabsContentProps>(
  ({ className, value, ...props }, ref) => {
    const { value: current } = useTabs();
    if (current !== value) {
      return null;
    }
    return (
      <div
        ref={ref}
        role="tabpanel"
        className={cn("ext-tabs-content pt-2", className)}
        {...props}
      />
    );
  }
);
TabsContent.displayName = "TabsContent";

export { Tabs, TabsList, TabsTrigger, TabsContent };

"use client";

import { useCallback, useEffect, useLayoutEffect, useRef } from "react";
import type { CSSProperties, ReactNode, ReactPortal } from "react";
import { createPortal } from "react-dom";

export type FloatingSide = "bottom" | "top" | "left" | "right";
export type FloatingAlign = "start" | "center" | "end";

export interface UseFloatingOptions {
  align?: FloatingAlign;
  onOpenChange?: (open: boolean) => void;
  open: boolean;
  side?: FloatingSide;
  sideOffset?: number;
}

const clamp = (value: number, max: number): number =>
  Math.max(8, Math.min(value, Math.max(8, max)));

export const useFloating = ({
  align = "center",
  onOpenChange,
  open,
  side = "bottom",
  sideOffset = 4,
}: UseFloatingOptions) => {
  const triggerRef = useRef<HTMLElement | null>(null);
  const contentRef = useRef<HTMLDivElement | null>(null);

  const close = useCallback(() => {
    onOpenChange?.(false);
  }, [onOpenChange]);

  const applyPosition = useCallback(() => {
    const trigger = triggerRef.current;
    const content = contentRef.current;
    if (!(trigger instanceof HTMLElement) || !content) {
      return;
    }
    const rect = trigger.getBoundingClientRect();
    const width = content.offsetWidth;
    const height = content.offsetHeight;

    let left: number | undefined;
    let top: number | undefined;
    let right: number | undefined;
    let bottom: number | undefined;
    const translate: string[] = [];

    if (side === "bottom" || side === "top") {
      if (side === "bottom") {
        top = clamp(rect.bottom + sideOffset, window.innerHeight - height);
      } else {
        bottom = window.innerHeight - rect.top + sideOffset;
      }
      if (align === "center") {
        left = clamp(rect.left + rect.width / 2, window.innerWidth - width);
        translate.push("translateX(-50%)");
      } else if (align === "end") {
        right = clamp(
          window.innerWidth - rect.right,
          window.innerWidth - width
        );
      } else {
        left = clamp(rect.left, window.innerWidth - width);
      }
    } else {
      if (side === "right") {
        left = clamp(rect.right + sideOffset, window.innerWidth - width);
      } else {
        right = window.innerWidth - rect.left + sideOffset;
      }
      if (align === "center") {
        top = clamp(rect.top + rect.height / 2, window.innerHeight - height);
        translate.push("translateY(-50%)");
      } else if (align === "end") {
        bottom = window.innerHeight - rect.bottom;
      } else {
        top = clamp(rect.top, window.innerHeight - height);
      }
    }

    content.style.left = left === undefined ? "" : `${left}px`;
    content.style.top = top === undefined ? "" : `${top}px`;
    content.style.right = right === undefined ? "" : `${right}px`;
    content.style.bottom = bottom === undefined ? "" : `${bottom}px`;
    content.style.transform = translate.join(" ");
  }, [align, side, sideOffset]);

  useLayoutEffect(() => {
    if (!open) {
      return;
    }
    applyPosition();
    const handleScroll = () => {
      applyPosition();
    };
    const handleResize = () => {
      applyPosition();
    };
    window.addEventListener("scroll", handleScroll, true);
    window.addEventListener("resize", handleResize);
    // The trigger can also move without a scroll or resize — a table grip
    // shifts when its row or column is added or deleted. Follow it per frame
    // so the open menu never detaches from its trigger.
    let frame: number;
    const follow = () => {
      applyPosition();
      frame = requestAnimationFrame(follow);
    };
    frame = requestAnimationFrame(follow);
    return () => {
      cancelAnimationFrame(frame);
      window.removeEventListener("scroll", handleScroll, true);
      window.removeEventListener("resize", handleResize);
    };
  }, [applyPosition, open]);

  useEffect(() => {
    if (!open) {
      return;
    }
    const handlePointerDown = (e: PointerEvent) => {
      const target = e.target as HTMLElement | null;
      if (
        target &&
        (triggerRef.current?.contains(target) ||
          contentRef.current?.contains(target))
      ) {
        return;
      }
      close();
    };
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        close();
      }
    };
    document.addEventListener("pointerdown", handlePointerDown, true);
    document.addEventListener("keydown", handleKeyDown, true);
    return () => {
      document.removeEventListener("pointerdown", handlePointerDown, true);
      document.removeEventListener("keydown", handleKeyDown, true);
    };
  }, [close, open]);

  const content = (children: ReactNode): null | ReactPortal =>
    open
      ? createPortal(
          <div
            ref={contentRef}
            data-ext-floating
            style={{ position: "fixed", zIndex: 60 } as CSSProperties}
          >
            {children}
          </div>,
          document.body
        )
      : null;

  return { content, triggerRef };
};

import { clsx } from "clsx";
import type { ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export const cn = (...inputs: ClassValue[]) => twMerge(clsx(inputs));
